export const LanguageProvider = ({ children }) => {
  const [language, setLanguage] = useState('pt'); // Default to Brazilian Portuguese (as user's prompt suggests)

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const storedLang = localStorage.getItem('portfolio-language');
      if (storedLang && (storedLang === 'en' || storedLang === 'pt')) {
        setLanguage(storedLang);
      } else {
        // Fallback to browser preference
        const browserLang = navigator.language || navigator.userLanguage;
        if (browserLang.startsWith('en')) {
          setLanguage('en');
        } else {
          setLanguage('pt');
        }
      }
    }
  }, []);

  const changeLanguage = (lang) => {
    if (lang === 'en' || lang === 'pt') {
      setLanguage(lang);
      if (typeof window !== 'undefined') {
        localStorage.setItem('portfolio-language', lang);
      }
    }
  };

  const t = (key) => {
    return translations[language][key] || key;
  };

  return (
    <LanguageContext.Provider value={{ language, changeLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};
