const React = require('react');
const { ThemeProvider } = require('./src/context/ThemeContext');
const { LanguageProvider } = require('./src/context/LanguageContext');

exports.wrapRootElement = ({ element }) => {
  return (
    <ThemeProvider>
      <LanguageProvider>
        {element}
      </LanguageProvider>
    </ThemeProvider>
  );
};
